                        value = _merge_grad(base, contribution)
                    assignments.append((node, value))
        for node, value in assignments:
            if value is not None:
                _ensure_finite_grad(value)
        for node, value in assignments:
            node.grad = value
        self._backward_record = (upstream, leaves)

